types:
export interface WorkflowPort {
    id: string;
    label?: string;
}

export interface WorkflowNode {
    id: string;
    label: string;
    description?: string;
    type?: string;
    x: number;
    y: number;
    width?: number;
    inputs?: WorkflowPort[];
    outputs?: WorkflowPort[];
    data?: unknown;
}

export interface WorkflowEdge {
    id: string;
    source: string;
    target: string;
    sourcePort: string;
    targetPort: string;
    label?: string;
}

export interface WorkflowValue {
    nodes: WorkflowNode[];
    edges: WorkflowEdge[];
}

export interface WorkflowViewport {
    x: number;
    y: number;
    zoom: number;
}

export interface WorkflowEditorProps extends Omit<React.ComponentProps<'section'>, 'onChange' | 'defaultValue'> {
    value?: WorkflowValue;
    defaultValue?: WorkflowValue;
    onValueChange?: (value: WorkflowValue) => void;
    onBeforeConnect?: (edge: WorkflowEdge, value: WorkflowValue) => string | undefined;
    onSelectionChange?: (selection: {
        kind: 'node' | 'edge';
        id: string;
    } | null) => void;
    renderNode?: (node: WorkflowNode) => React.ReactNode;
    createNode?: () => Omit<WorkflowNode, 'id' | 'x' | 'y'>;
    readOnly?: boolean;
    disabled?: boolean;
    allowCycles?: boolean;
    snapGrid?: number;
    height?: number;
    label?: string;
    viewport?: WorkflowViewport;
    defaultViewport?: WorkflowViewport;
    onViewportChange?: (viewport: WorkflowViewport) => void;
    fitView?: boolean;
}

interface WorkflowContext {
    graph: WorkflowValue;
    positions: Record<string, {
        x: number;
        y: number;
    }>;
    setPositions: React.Dispatch<React.SetStateAction<Record<string, {
        x: number;
        y: number;
    }>>>;
    commit: (value: WorkflowValue) => void;
    readOnly: boolean;
    disabled: boolean;
    height: number;
    snapGrid: number;
    selection: {
        kind: 'node' | 'edge';
        id: string;
    } | null;
    select: (selection: {
        kind: 'node' | 'edge';
        id: string;
    } | null) => void;
    pending: {
        node: string;
        port: string;
    } | null;
    setPending: (pending: {
        node: string;
        port: string;
    } | null) => void;
    connect: (node: string, port: string) => void;
    error: string;
    renderNode?: WorkflowEditorProps['renderNode'];
    view: {
        x: number;
        y: number;
        zoom: number;
    };
    setView: React.Dispatch<React.SetStateAction<{
        x: number;
        y: number;
        zoom: number;
    }>>;
    host: React.RefObject<HTMLDivElement | null>;
    undo: () => void;
    redo: () => void;
    canUndo: boolean;
    canRedo: boolean;
    remove: () => void;
    add: () => void;
    fit: () => void;
}

export function WorkflowNodeCard({
  node,
  direction = 'ltr',
}: {
  node: WorkflowNode
  direction?: 'ltr' | 'rtl'
}): React.JSX.Element

export function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }): React.JSX.Element

export interface UIConfig {
    density: 'comfortable' | 'compact';
    direction: 'ltr' | 'rtl';
    locale: string;
}

export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
    density?: UIConfig['density'];
    direction?: UIConfig['direction'];
    locale?: string;
    accent?: string;
    radius?: number;
}

export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}): readonly [T, (next: T | ((previous: T) => T)) => void]

