    code: string;
    filename: string;
    language: CodeLanguage;
    lineNumbers: boolean;
    startLine: number;
    highlightedLines: number[];
    wrap: boolean;
    setWrap: (value: boolean) => void;
    copyable: boolean;
    downloadable: boolean;
    onCopy?: CodeBlockProps['onCopy'];
    tokens: ThemedTokenWithVariants[][] | null;
    status: string;
    setStatus: (status: string) => void;
}

export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}): readonly [T, (next: T | ((previous: T) => T)) => void]

export interface DiffRow {
    oldLine?: number;
    newLine?: number;
    oldText?: string;
    newText?: string;
    oldNoNewline?: boolean;
    newNoNewline?: boolean;
    kind: 'equal' | 'change' | 'add' | 'remove';
}

export interface DiffViewerProps extends Omit<React.ComponentProps<'section'>, 'onCopy'> {
    before: string;
    after: string;
    beforeLabel?: string;
    afterLabel?: string;
    label?: string;
    mode?: 'split' | 'inline';
    defaultMode?: 'split' | 'inline';
    onModeChange?: (mode: 'split' | 'inline') => void;
    contextLines?: number;
    ignoreWhitespace?: boolean;
    wordHighlight?: boolean;
    copyable?: boolean;
    maxCharacters?: number;
    maxLines?: number;
    timeout?: number;
    onCopy?: (text: string, side: 'before' | 'after') => void | Promise<void>;
}

interface DiffContext {
    rows: DiffRow[];
    mode: 'split' | 'inline';
    setMode: (mode: 'split' | 'inline') => void;
    beforeLabel: string;
    afterLabel: string;
    before: string;
    after: string;
    contextLines: number;
    wordHighlight: boolean;
    copyable: boolean;
    onCopy: DiffViewerProps['onCopy'];
    status: string;
    setStatus: (status: string) => void;
    showAll: boolean;
    setShowAll: (show: boolean) => void;
}

export interface StreamingMarkdownProps extends Omit<React.ComponentProps<'div'>, 'children'>, TextStreamOptions {
    content: string;
    streaming?: boolean;
    breaks?: boolean;
    allowImages?: boolean;
    maxCharacters?: number;
    renderCode?: (code: string, language: string) => React.ReactNode;
    renderImage?: (image: {
        src: string;
        alt: string;
        title?: string;
    }) => React.ReactNode;
    /** An application renderer for fenced math, latex or mermaid blocks; no rendering engine is bundled. */
    renderMath?: (source: string) => React.ReactNode;
    renderDiagram?: (source: string) => React.ReactNode;
}

export interface TextStreamOptions {
    /** Reveal incoming text progressively, or display each received chunk immediately. */
    textAnimation?: 'typewriter' | 'none';
    /** Graphemes revealed per second, from 1 to 1,000. Defaults to 60. */
    charactersPerSecond?: number;
}

export function useTextStream(content: string, {
    streaming = false,
    textAnimation = 'typewriter',
    charactersPerSecond = 60,
    streamKey,
    immediate = false,
  }: TextStreamOptions & {
    streaming?: boolean
    streamKey?: string | number
    immediate?: boolean
  } = {}): { text: string; isRevealing: boolean; }

