export interface FileBrowserEntry {
    id: string;
    parentId?: string | null;
    name: string;
    kind: 'file' | 'folder';
    size?: number;
    modifiedAt?: string;
    mimeType?: string;
    thumbnail?: string;
    disabled?: boolean;
    data?: unknown;
}

export interface FileOperationContext {
    /** Cancellation is requested through this signal. Reject with AbortError to confirm it; resolve when the operation completes. */
    signal: AbortSignal;
}

export interface FileBrowserProps extends Omit<React.ComponentProps<'section'>, 'onChange' | 'onError'> {
    entries: FileBrowserEntry[];
    folderId?: string | null;
    defaultFolderId?: string | null;
    onFolderChange?: (id: string | null) => void;
    selectedIds?: string[];
    defaultSelectedIds?: string[];
    onSelectionChange?: (ids: string[]) => void;
    multiple?: boolean;
    view?: 'grid' | 'list';
    defaultView?: 'grid' | 'list';
    onViewChange?: (view: 'grid' | 'list') => void;
    sortBy?: 'name' | 'size' | 'modified';
    defaultSortBy?: 'name' | 'size' | 'modified';
    onSortByChange?: (sort: 'name' | 'size' | 'modified') => void;
    sortDirection?: 'asc' | 'desc';
    defaultSortDirection?: 'asc' | 'desc';
    onSortDirectionChange?: (direction: 'asc' | 'desc') => void;
    searchScope?: 'folder' | 'all';
    pageSize?: number;
    maxEntries?: number;
    label?: string;
    disabled?: boolean;
    accept?: string;
    onOpen?: (entry: FileBrowserEntry) => void;
    onDownload?: (entry: FileBrowserEntry, context: FileOperationContext) => void | Promise<void>;
    onCreateFolder?: (name: string, parentId: string | null, context: FileOperationContext) => void | Promise<void>;
    onRename?: (entry: FileBrowserEntry, name: string, context: FileOperationContext) => void | Promise<void>;
    onMove?: (entries: FileBrowserEntry[], parentId: string | null, context: FileOperationContext) => void | Promise<void>;
    onDelete?: (entries: FileBrowserEntry[], context: FileOperationContext) => void | Promise<void>;
    onUpload?: (files: File[], parentId: string | null, context: FileOperationContext) => void | Promise<void>;
    onError?: (error: Error) => void;
    renderPreview?: (entry: FileBrowserEntry) => React.ReactNode;
}

type FileDialog = {
    kind: 'create' | 'rename' | 'move' | 'delete' | 'info';
    entries: FileBrowserEntry[];
} | null;

interface FilesContext {
    entries: FileBrowserEntry[];
    map: Map<string, FileBrowserEntry>;
    folderId: string | null;
    path: FileBrowserEntry[];
    navigate: (id: string | null) => void;
    query: string;
    setQuery: (query: string) => void;
    view: 'grid' | 'list';
    setView: (view: 'grid' | 'list') => void;
    sort: string;
    setSort: (sort: 'name' | 'size' | 'modified') => void;
    direction: 'asc' | 'desc';
    setDirection: (direction: 'asc' | 'desc') => void;
    selected: Set<string>;
    select: (id: string, checked: boolean, range?: boolean) => void;
    selectAll: () => void;
    clearSelection: () => void;
    filtered: FileBrowserEntry[];
    pageItems: FileBrowserEntry[];
    page: number;
    setPage: (page: number) => void;
    pages: number;
    disabled: boolean;
    busy: boolean;
    operation: string;
    operationError: string;
    dialog: FileDialog;
    setDialog: (dialog: FileDialog) => void;
    perform: (name: string, action: (context: FileOperationContext) => void | Promise<void>) => Promise<void>;
    cancel: () => void;
    open: (entry: FileBrowserEntry) => void;
    callbacks: Pick<FileBrowserProps, 'onCreateFolder' | 'onRename' | 'onMove' | 'onDelete' | 'onUpload' | 'onDownload'>;
    accept?: string;
    maxEntries: number;
    renderPreview: FileBrowserProps['renderPreview'];
}

export function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }): React.JSX.Element

export interface InputProps extends Omit<React.ComponentProps<'input'>, 'prefix'> {
    leading?: React.ReactNode;
    trailing?: React.ReactNode;
    allowClear?: boolean;
    showCount?: boolean;
    passwordToggle?: boolean;
    onValueChange?: (value: string) => void;
}

export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}): readonly [T, (next: T | ((previous: T) => T)) => void]

export function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>): React.JSX.Element

export function DialogContent({
  className,
  children,
  showCloseButton = true,
  draggable,
  resizable,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content> & {
  showCloseButton?: boolean
  draggable?: boolean
  resizable?: boolean
}): React.JSX.Element

export function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: React.ComponentProps<'div'> & {
  showCloseButton?: boolean
}): React.JSX.Element

export function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>): React.JSX.Element

export interface UIConfig {
    density: 'comfortable' | 'compact';
    direction: 'ltr' | 'rtl';
    locale: string;
}

export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
    density?: UIConfig['density'];
    direction?: UIConfig['direction'];
    locale?: string;
    accent?: string;
    radius?: number;
}

