import * as React from 'react'
import {
  Folder,
  File,
  FileImage,
  FileText,
  FileCode,
  Music2,
  Video,
  Search,
  LayoutGrid,
  List,
  ArrowDownAZ,
  ArrowUpAZ,
  FolderPlus,
  Upload,
  Trash2,
  Pencil,
  FolderInput,
  Download,
