            <tr>
              {columns.map((column, i) => (
                <th
                  key={i}
                  scope="col"
                  className="border-b px-3 py-2 text-start font-medium text-muted-foreground"
                >
                  {column}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.id}>
                {row.cells.map((cell, i) => (
                  <td key={i} className="border-b px-3 py-2 last:border-b-0">
                    {cell ?? '—'}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </details>
  )
}

